import React, { useState, useEffect, useRef } from "react";
import axios from "axios";
import QRCode from "react-qr-code";
import { useLocation } from "react-router-dom";
import Navbar from "./Navbar";
import html2canvas from "html2canvas";
import * as faceapi from "face-api.js";

function Register() {
  const location = useLocation();
  const eventId = location.state?.eventId || "";
  const eventName = location.state?.eventName || "No Event Selected";

  const [formData, setFormData] = useState({
    name: "",
    college_name: "",
    phone: "",
    email: "",
    event_id: eventId,
  });
  const [showQR, setShowQR] = useState(false);
  const [screenshot, setScreenshot] = useState(null);
  const [statusMsg, setStatusMsg] = useState("");
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [userId, setUserId] = useState("");
  const [approved, setApproved] = useState(false);
  const [photo, setPhoto] = useState("");

  const videoRef = useRef(null);
  const canvasRef = useRef(null);
  const idCardRef = useRef(null);
  const streamRef = useRef(null);

  useEffect(() => {
    faceapi.nets.tinyFaceDetector.loadFromUri("/models");
  }, []);

  // Polling logic fixed to detect status change
  useEffect(() => {
    let interval;
    if (userId && !approved) {
      interval = setInterval(async () => {
        try {
          const res = await axios.get(
            `http://localhost:5000/verify-user/${userId}`,
          );
          if (res.data.success && res.data.user.payment_status === "approved") {
            setApproved(true);
            setStatusMsg("✅ Approved! Take your photo.");
            clearInterval(interval);
          }
        } catch (err) {
          console.log(err);
        }
      }, 3000);
    }
    return () => clearInterval(interval);
  }, [userId, approved]);

  const confirmPayment = async () => {
    if (!screenshot) return alert("Upload screenshot!");
    setIsSubmitting(true);
    const form = new FormData();
    Object.keys(formData).forEach((key) => form.append(key, formData[key]));
    form.append("screenshot", screenshot);

    try {
      const res = await axios.post("http://localhost:5000/register", form);
      if (res.data.success) {
        setUserId(res.data.userId);
        setStatusMsg("⏳ Waiting for admin approval...");
      } else if (res.data.message === "Already Uploaded") {
        alert("Error: You have already uploaded a payment for this event!");
        setStatusMsg("❌ Duplicate submission detected.");
      }
    } catch {
      alert("Upload failed");
    } finally {
      setIsSubmitting(false);
    }
  };

  const openCamera = async () => {
    const stream = await navigator.mediaDevices.getUserMedia({ video: true });
    streamRef.current = stream;
    videoRef.current.srcObject = stream;
    videoRef.current.play();
  };

  const capturePhoto = async () => {
    const detections = await faceapi.detectAllFaces(
      videoRef.current,
      new faceapi.TinyFaceDetectorOptions(),
    );
    if (detections.length !== 1)
      return alert("Ensure only one face is visible");
    const canvas = canvasRef.current;
    canvas.width = videoRef.current.videoWidth;
    canvas.height = videoRef.current.videoHeight;
    canvas.getContext("2d").drawImage(videoRef.current, 0, 0);
    setPhoto(canvas.toDataURL());
    streamRef.current.getTracks().forEach((t) => t.stop());
  };

  const downloadCard = () => {
    html2canvas(idCardRef.current).then((canvas) => {
      const link = document.createElement("a");
      link.download = "ID_Card.png";
      link.href = canvas.toDataURL();
      link.click();
    });
  };

  const box = {
    padding: "20px",
    background: "#222",
    width: "320px",
    margin: "auto",
    borderRadius: "10px",
  };
  const btn = {
    padding: "10px",
    background: "orange",
    border: "none",
    cursor: "pointer",
    marginTop: "10px",
  };

  return (
    <div
      style={{
        textAlign: "center",
        color: "white",
        background: "#111",
        minHeight: "100vh",
      }}
    >
      <Navbar />
      <h2>🚀 Event Registration</h2>
      {!showQR && (
        <form
          onSubmit={(e) => {
            e.preventDefault();
            setShowQR(true);
          }}
          style={box}
        >
          <input
            placeholder="Name"
            style={{ width: "90%", margin: "5px" }}
            onChange={(e) => setFormData({ ...formData, name: e.target.value })}
            required
          />
          <input
            placeholder="Email"
            style={{ width: "90%", margin: "5px" }}
            onChange={(e) =>
              setFormData({ ...formData, email: e.target.value })
            }
            required
          />
          <button style={btn}>Proceed to Pay</button>
        </form>
      )}
      {showQR && !approved && (
        <div style={box}>
          {!userId ? (
            <>
              <QRCode
                value={`upi://pay?pa=arunsekar664@okaxis&am=100`}
                size={150}
              />
              <input
                type="file"
                onChange={(e) => setScreenshot(e.target.files[0])}
              />
              <button
                style={btn}
                onClick={confirmPayment}
                disabled={isSubmitting}
              >
                Submit Payment
              </button>
            </>
          ) : (
            <p>{statusMsg}</p>
          )}
        </div>
      )}
      {approved && !photo && (
        <div style={box}>
          <button style={btn} onClick={openCamera}>
            Open Camera
          </button>
          <video ref={videoRef} style={{ width: "100%" }} />
          <button style={btn} onClick={capturePhoto}>
            Capture
          </button>
          <canvas ref={canvasRef} style={{ display: "none" }} />
        </div>
      )}
      {photo && (
        <div
          ref={idCardRef}
          style={{
            background: "white",
            color: "black",
            padding: "20px",
            width: "250px",
            margin: "auto",
          }}
        >
          <h3>EVENT PASS</h3>
          <img src={photo} alt="" style={{ width: "100px" }} />
          <p>{formData.name}</p>
          <QRCode value={userId} size={80} />
          <button style={btn} onClick={downloadCard}>
            Download
          </button>
        </div>
      )}
    </div>
  );
}
export default Register;
